<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {auth,bootstrapAuth,clearAuth,switchEdition} from '../auth/bootstrap';import {responseError} from '../http';import {useBusinessStore,businessApi} from '../stores/business';import {useSessionStore} from '../stores/session';import {useRunStore} from '../stores/run';import {useEvidenceUpload} from '../stores/evidence-upload';import {useConversationController} from '../composables/useConversationController';import {useVisibleRefresh} from '../composables/useVisibleRefresh';
import {useMobileNavigation} from './navigation';import {useMobileViewport} from './viewport';import type {Notice} from '@shared/mobile';
import MobileHome from './MobileHome.vue';import MobileSessions from './MobileSessions.vue';import MobileConversation from './MobileConversation.vue';import MobileRooms from './MobileRooms.vue';import MobileMessages from './MobileMessages.vue';import MobileProfile from './MobileProfile.vue';import MobileTask from './MobileTask.vue';import ScheduledJobsPanel from '../components/ScheduledJobsPanel.vue';import EvidencePanel from '../components/EvidencePanel.vue';
const business=useBusinessStore(),session=useSessionStore(),run=useRunStore(),upload=useEvidenceUpload(),navigation=useMobileNavigation(auth.target.value),{route,sheet,error:routeError}=navigation,{keyboard}=useMobileViewport(),authed=auth.authenticated,loading=ref(true),error=ref(auth.error.value),account=ref(''),password=ref(''),loggingIn=ref(false),unread=ref<number|null>(null),content=ref<HTMLElement>(),offline=ref(!navigator.onLine);
const controller=useConversationController(id=>navigation.go({view:'conversation',conversationId:id},route.value.view==='conversation'));
const title=computed(()=>({home:'工作台',assistant:'助手',conversation:'会话',rooms:'实验室',room:'实验室详情',automation:'自动化',job:'规则详情',task:'正式任务',messages:'消息中心',notice:'通知详情',profile:'我的',evidence:'证据与资料'} as Record<string,string>)[route.value.view]||'LabOps');
const activeTab=computed(()=>['conversation','assistant'].includes(route.value.view)?'assistant':['rooms','room','task','evidence'].includes(route.value.view)?'rooms':['automation','job'].includes(route.value.view)?'automation':route.value.view==='profile'?'profile':'home');
if(authed.value&&auth.error.value)routeError.value=auth.error.value;
const tabs=[{view:'home',label:'工作台',icon:'M3 10h7V3H3z M14 3v7h7V3z M3 14v7h7v-7z M14 14v7h7v-7z'},{view:'assistant',label:'助手',icon:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5'},{view:'rooms',label:'实验室',icon:'M4 21V4h16v17 M8 8h2 M14 8h2 M8 12h2 M14 12h2 M10 21v-5h4v5'},{view:'automation',label:'自动化',icon:'M12 3v3 M12 18v3 M3 12h3 M18 12h3 M5.6 5.6l2 2 M16.4 16.4l2 2 M5.6 18.4l2-2 M16.4 7.6l2-2 M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8'},{view:'profile',label:'我的',icon:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2'}];
async function notices(){if(!business.connected)return;try{const result=await businessApi<{notifications:Notice[]}>('proxy/notifications?limit=100');unread.value=result.notifications.filter(n=>!n.readAt).length;}catch{unread.value=null;}}
async function workspace(){loading.value=true;try{await business.refresh();if(!business.connected)throw new Error(business.error||'主系统业务接口暂不可用，恢复后重新读取');await session.loadConversations();await notices();error.value='';}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
onMounted(async()=>{if(authed.value)await workspace();else loading.value=false;});
async function login(){if(loggingIn.value||!account.value.trim()||!password.value)return;loggingIn.value=true;error.value='';try{if(auth.mode.value==='native'){const res=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account:account.value.trim(),password:password.value})});if(!res.ok)throw await responseError(res);}sessionStorage.removeItem('labops.manual-logout');sessionStorage.setItem('labops.auth',account.value.trim());password.value='';await bootstrapAuth(true);if(!authed.value)throw new Error(auth.error.value||'身份验证失败');await workspace();}catch(e){error.value=(e as Error).message;}finally{loggingIn.value=false;}}
function clearDrafts(){for(let i=localStorage.length-1;i>=0;i--){const key=localStorage.key(i);if(key?.startsWith('labops.native-draft:'))localStorage.removeItem(key);}}
async function logout(){sessionStorage.setItem('labops.manual-logout','1');controller.dispose();session.clearPrivate();upload.clearPrivate();business.clearPrivate();clearDrafts();clearAuth();unread.value=null;navigation.go({view:'home'},true);try{const response=await fetch('/api/auth/logout',{method:'POST'});if(!response.ok)throw await responseError(response);error.value='';}catch(e){error.value='已清空本机工作区，服务端退出尚未确认：'+(e as Error).message;}}
useVisibleRefresh(notices,()=>authed.value&&!run.inputLocked);
const scrolls=new Map<string,number>();watch(route,async(next,previous)=>{if(previous)scrolls.set(JSON.stringify(previous),content.value?.scrollTop||0);auth.target.value=next;await nextTick();if(content.value)content.value.scrollTop=scrolls.get(JSON.stringify(next))||0;});
watch(()=>business.scopeKey,(next,previous)=>{if(previous&&next!==previous){controller.dispose();session.clearPrivate();upload.clearPrivate();unread.value=null;scrolls.clear();}});
const connectivity=()=>offline.value=!navigator.onLine;window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);onUnmounted(()=>{window.removeEventListener('online',connectivity);window.removeEventListener('offline',connectivity);controller.dispose();});
</script>
<template><div class="mobile-shell" :class="{'mobile-keyboard':keyboard}"><template v-if="!authed"><main class="mobile-login"><div class="mobile-brand"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3h8 M9 3v6L4 19q0 2 2 2h12q2 0 2-2l-5-10V3 M8 14h8"/></svg><b>LabOps</b><span>实验室工作助手</span></div><h1>使用主系统账号登录</h1><p>管理员与志愿者身份由主系统识别。</p><form class="mobile-form" @submit.prevent="login"><label for="mobile-account">账号<input id="mobile-account" v-model="account" autocomplete="username" required maxlength="100"></label><label for="mobile-password">密码<input id="mobile-password" v-model="password" type="password" autocomplete="current-password" required maxlength="200"></label><p v-if="error" role="alert">{{error}}</p><button class="mobile-primary" :disabled="loggingIn">{{loggingIn?'正在验证…':'登录'}}</button></form><p>学生请使用主系统中的共享聊天入口。</p></main></template><template v-else><header class="mobile-header"><button v-if="!['home','assistant','rooms','automation','profile'].includes(route.view)" aria-label="返回" @click="navigation.back"><svg viewBox="0 0 24 24"><path d="m15 5-7 7 7 7"/></svg></button><div><b>{{title}}</b><small>{{business.profile?.username||auth.profile.value?.username}} · {{business.profile?.identity==='admin'?'管理员':'志愿者'}}</small></div><button aria-label="账户菜单" @click="navigation.openSheet('account')"><svg viewBox="0 0 24 24"><path d="M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2"/></svg></button><button aria-label="消息中心" @click="navigation.go({view:'messages'})"><svg viewBox="0 0 24 24"><path d="M6 17V9a6 6 0 0 1 12 0v8l2 2H4z M10 21h4"/></svg><span v-if="unread!==null&&unread>0" class="mobile-unread">{{unread>99?'99+':unread}}</span><span v-else-if="unread===null">?</span></button></header><p v-if="offline" class="mobile-offline" role="status">网络未连接，输入保留。恢复后按原会话或方案编号回查。</p><main ref="content" class="mobile-content" :class="{'mobile-content-conversation':route.view==='conversation'}"><p v-if="routeError" role="alert">{{routeError}}</p><p v-if="loading" class="mobile-state" role="status">正在恢复本人工作区…</p><div v-else-if="error" class="mobile-state" role="alert"><p>{{error}}</p><button @click="workspace">重新读取</button><button @click="logout">退出登录</button></div><template v-else-if="business.connected"><MobileHome v-if="route.view==='home'" :key="business.scopeKey" @navigate="navigation.go"/><MobileSessions v-else-if="route.view==='assistant'" :section="route.section" @navigate="navigation.go"/><MobileConversation v-else-if="route.view==='conversation'&&route.conversationId" :conversation-id="route.conversationId" :controller="controller"/><MobileRooms v-else-if="route.view==='rooms'||route.view==='room'" :room-id="route.roomId" :action="route.action" @navigate="navigation.go"/><ScheduledJobsPanel v-else-if="route.view==='automation'||route.view==='job'" :inline="true" :job-id="route.jobId" :readonly="run.inputLocked" @navigate="navigation.go"/><MobileTask v-else-if="route.view==='task'&&route.taskId" :task-id="route.taskId"/><MobileMessages v-else-if="route.view==='messages'||route.view==='notice'" :notice-id="route.noticeId" @navigate="navigation.go" @changed="notices"/><MobileProfile v-else-if="route.view==='profile'" @logout="logout" @navigate="navigation.go"/><EvidencePanel v-else-if="route.view==='evidence'" :inline="true" :room-id="route.roomId" :issue-id="route.issueId" :readonly="run.inputLocked"/></template></main><button v-if="run.inputLocked&&route.view!=='conversation'&&controller.activeConversation.value" class="mobile-run-banner" @click="navigation.go({view:'conversation',conversationId:controller.activeConversation.value})">本人的会话仍在生成 · 返回查看</button><nav v-show="!keyboard" class="mobile-bottom-nav" aria-label="主要导航"><button v-for="tab in tabs" :key="tab.view" :aria-current="activeTab===tab.view?'page':undefined" @click="navigation.go({view:tab.view})"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="tab.icon"/></svg><span>{{tab.label}}</span></button></nav><div v-if="sheet" class="mobile-sheet-mask" @click.self="navigation.closeSheet"><section class="mobile-sheet" role="dialog" aria-modal="true"><h2>本人账户</h2><p>{{business.profile?.username}} · {{business.profile?.identity==='admin'?'管理员':'志愿者'}}</p><button @click="navigation.go({view:'profile'})">身份、主题和提醒偏好</button><button @click="switchEdition('desktop',route)">使用桌面版（记住 7 天）</button><button @click="navigation.closeSheet">关闭账户菜单</button><button class="mobile-danger" @click="logout">退出登录</button></section></div></template></div></template>
